package com.hotelos.dpc.core

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject

/**
 * Kotlin mirror of packages/protocol (TypeScript/zod is the source of truth).
 * Contract tests (ProtocolContractTest) parse fixtures generated by the TS side.
 */
const val PROTOCOL_VERSION = 1

val ProtocolJson = Json {
    ignoreUnknownKeys = true // forward compatible: newer servers may add fields
    encodeDefaults = true
    explicitNulls = false
}

@Serializable enum class AppDesiredState { ALLOWED, SUSPENDED, HIDDEN, UNINSTALLED }
@Serializable enum class KioskMode { ENFORCED_HOME, STRICT_LOCK_TASK }
@Serializable enum class CleanupPolicy { KEEP, CLEAR_DATA, RESET_SESSION }
@Serializable enum class UnlistedAppsRule { SUSPENDED, UNMANAGED }

@Serializable
data class ApkArtifact(
    val versionCode: Long,
    val versionName: String,
    val url: String,
    val sha256: String,
    val signerSha256: String,
    val sizeBytes: Long,
    /** MAINTENANCE: updates of an installed app wait for the hotel maintenance window. */
    val updateWindow: String = "MAINTENANCE",
)

@Serializable
data class AppPolicy(
    val packageName: String,
    val state: AppDesiredState,
    val visibleInLauncher: Boolean,
    val order: Int,
    val label: String? = null,
    val cleanup: CleanupPolicy,
    val artifact: ApkArtifact? = null,
)

@Serializable
data class Branding(
    val hotelName: String,
    val logoUrl: String? = null,
    val backgroundUrl: String? = null,
    val primaryColor: String,
    val accentColor: String,
)

@Serializable
data class LauncherPolicy(
    val template: String,
    val language: String,
    val availableLanguages: List<String>,
    val timezone: String,
    val branding: Branding,
    val welcomeMessage: Map<String, String> = emptyMap(),
    val roomNumber: String? = null,
    val guestFirstName: String? = null,
    val modules: List<String>,
    val idleReturnHomeMinutes: Int,
)

@Serializable
data class KioskPolicy(
    val mode: KioskMode,
    val launcherPackage: String,
    val lockTaskExtraPackages: List<String>,
    val systemPackagesToBlock: List<String>,
    val unlistedLaunchableApps: UnlistedAppsRule = UnlistedAppsRule.SUSPENDED,
)

@Serializable data class MaintenanceWindow(val start: String, val end: String)

@Serializable
data class SystemPolicy(
    val timezone: String,
    val autoTime: Boolean,
    val maintenanceWindow: MaintenanceWindow,
    val telemetryIntervalSec: Int,
    val screenCaptureDisabled: Boolean,
)

@Serializable data class WifiNetwork(val ssid: String, val security: String, val passphraseRef: String? = null)
@Serializable data class IptvPolicy(val enabled: Boolean, val lineupId: String? = null)

@Serializable
data class EffectivePolicy(
    val schema: Int,
    val deviceId: String,
    val version: Int,
    val issuedAt: String,
    val kiosk: KioskPolicy,
    val restrictions: List<String>,
    val apps: List<AppPolicy>,
    val launcher: LauncherPolicy,
    val system: SystemPolicy,
    val wifi: List<WifiNetwork> = emptyList(),
    val iptv: IptvPolicy,
    val warnings: List<String> = emptyList(),
)

@Serializable
data class SignedPolicy(val kid: String, val alg: String, val payload: String, val signature: String, val version: Int)

@Serializable data class PolicyPublicKey(val kid: String, val spki: String)

@Serializable
data class HardwareInfo(
    val manufacturer: String,
    val model: String,
    val brand: String? = null,
    val buildFingerprint: String,
    val sdkInt: Int,
    val androidRelease: String,
    val supportedAbis: List<String>,
    val serial: String? = null,
    val androidId: String? = null,
    val macAddress: String? = null,
    val ramMb: Int? = null,
    val storageTotalMb: Int? = null,
)

@Serializable
data class EnrollRequest(
    val enrollmentToken: String,
    val publicKey: String,
    val attestationChain: List<String>? = null,
    val hardware: HardwareInfo,
    val dpcVersionCode: Int,
    val isDeviceOwner: Boolean,
)

@Serializable
data class EnrollResponse(
    val deviceId: String,
    val hotelId: String,
    val pairingCode: String,
    val pairingExpiresAt: String,
    val policyPublicKeys: List<PolicyPublicKey>,
    val wsUrl: String,
)

@Serializable data class PairingCode(val pairingCode: String, val pairingExpiresAt: String)

@Serializable
data class ObservedApp(
    val packageName: String,
    val label: String? = null,
    val versionCode: Long,
    val versionName: String? = null,
    val system: Boolean,
    val enabled: Boolean,
    val suspended: Boolean,
    val hidden: Boolean,
    val hasLauncherEntry: Boolean,
    val signerSha256: String? = null,
    val iconHash: String? = null,
    val canSuspend: Boolean? = null,
    val canHide: Boolean? = null,
)

@Serializable data class ReconcileError(val key: String, val message: String)

@Serializable
data class NetworkInfo(val type: String, val ssid: String? = null, val ip: String? = null)

@Serializable
data class DeviceStateReport(
    val policyVersionApplied: Int,
    val reconcileErrors: List<ReconcileError>,
    val isDeviceOwner: Boolean,
    val kioskActive: Boolean,
    val launcherHealthy: Boolean,
    val dpcVersionCode: Int,
    val launcherVersionCode: Int? = null,
    val iptvVersionCode: Int? = null,
    val apps: List<ObservedApp>,
    val inventoryIsDelta: Boolean,
    val removedPackages: List<String> = emptyList(),
    val storageFreeMb: Int? = null,
    val ramFreeMb: Int? = null,
    val uptimeSec: Int? = null,
    val network: NetworkInfo? = null,
    val buildFingerprint: String? = null,
)

@Serializable
data class DeviceCommand(
    val id: String,
    val type: String,
    val payload: JsonObject,
    val createdAt: String,
    val expiresAt: String,
)

@Serializable
data class CommandResult(val status: String, val message: String? = null, val data: JsonObject? = null)

@Serializable data class CleanupAppResult(val packageName: String, val action: String, val ok: Boolean, val message: String? = null)
@Serializable data class CleanupReport(val outcome: String, val apps: List<CleanupAppResult>, val finishedAt: String)

/** WebSocket frames. */
@Serializable
sealed interface WsServerMessage {
    @Serializable @SerialName("welcome") data class Welcome(val serverTime: String, val latestPolicyVersion: Int) : WsServerMessage
    @Serializable @SerialName("policy.changed") data class PolicyChanged(val version: Int) : WsServerMessage
    @Serializable @SerialName("command") data class Command(val command: DeviceCommand) : WsServerMessage
    @Serializable @SerialName("error") data class Error(val code: String, val message: String) : WsServerMessage
}

@Serializable
sealed interface WsClientMessage {
    @Serializable @SerialName("hello") data class Hello(val policyVersion: Int, val protocol: Int = PROTOCOL_VERSION) : WsClientMessage
    @Serializable @SerialName("heartbeat") data object Heartbeat : WsClientMessage
    @Serializable @SerialName("command.update") data class CommandUpdate(val commandId: String, val result: CommandResult) : WsClientMessage
}

/** Discriminator is "t" on the wire. */
val WsJson = Json(ProtocolJson) { classDiscriminator = "t" }
